import {windowPages,windowForms,windowRelations,windowStories} from './two-windows-content.mjs';
import {windowsView,startWindows,setWindowsPage,setWindowsAccount,chooseWindowClaim,nextWindowClaim,chooseWindowRelation,toggleWindowLine,chooseWindowCard,setWindowWords,setWindowReading,addWindowSupport,resumeWindows,checkWindowClaim,checkWindowMessage,keepWindowWords,windowClaimMatches,windowMessageMatches} from './two-windows-core.mjs';
import {hearButton} from './play-media.mjs';
import {windowReminder} from './two-windows-art.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(attrs,text,selected=false)=>`<button type="button" class="${selected?'primary':'secondary'}" ${attrs}>${esc(text)}</button>`;
const relation=id=>windowRelations.find(x=>x.id===id)?.label||id||'No relationship chosen';
const formName=id=>windowForms.find(x=>x.id===id)?.label||id;
const passageName=(source,id)=>source.accounts.find(a=>a.id===id)?.name||id;
const help='Read the two accounts together. Directly said means a teller says it. Worked out from clues means details support it without saying it directly. Text says otherwise needs a detail that conflicts with it. Not enough information means a needed fact is missing, not that the statement is false. You can read, listen, or think with someone.';
const lineName=(source,id)=>{const a=source.accounts.find(a=>a.lines.some(l=>l.id===id));return a?`${a.id.toUpperCase()}${a.lines.findIndex(l=>l.id===id)+1}`:id;};
function sourceLines(source,ids,empty='No lines selected.'){return ids.length?`<ul>${ids.map(id=>{const account=source.accounts.find(a=>a.lines.some(l=>l.id===id)),line=account?.lines.find(l=>l.id===id);return `<li><strong>${esc(lineName(source,id))}${account?' · '+esc(account.name):''}:</strong> ${line?esc(line.text):'Recorded line identifier'}</li>`;}).join('')}</ul>`:`<p>${esc(empty)}</p>`;}
function account(source,acct,{selectable=false,selected=[]}={}){return `<section class="windows-account" aria-label="Account ${acct.id.toUpperCase()} by ${esc(acct.name)}"><h3>Account ${acct.id.toUpperCase()} · ${esc(acct.name)}</h3><p class="windows-fiction">Original fiction</p><ol>${acct.lines.map((l,n)=>`<li>${selectable?`<button type="button" class="windows-line${selected.includes(l.id)?' selected':''}" data-window-line="${l.id}" aria-pressed="${selected.includes(l.id)}"><span class="windows-line-number">${n+1}</span><span>${esc(l.text)}<small>Line ${acct.id.toUpperCase()}${n+1}${selected.includes(l.id)?' · selected':''}</small></span></button>`:`<span class="windows-line-number">${n+1}</span><p>${esc(l.text)}<small>Line ${acct.id.toUpperCase()}${n+1}</small></p>`}</li>`).join('')}</ol>${hearButton(`${acct.name}. ${acct.lines.map(l=>l.text).join(' ')}`,`Hear ${acct.name}’s account`)}</section>`;}
function sources(source,selectable=false,selected=[]){return `<div class="windows-paired-accounts">${source.accounts.map(a=>account(source,a,{selectable,selected})).join('')}</div>`;}
function sourceDetails(source){return `<details class="windows-frozen-source"><summary>Passages kept with this visit · original fiction</summary><p><strong>${esc(source.title)}</strong> · ${esc(formName(source.form))}</p>${sources(source)}</details>`;}
function readingReport(r){return `<details id="windows-reading" data-visit="${r.id}"><summary>How did we read?</summary><div class="windows-choices" role="group" aria-label="Optional reading report">${[['unobserved','Reading not observed'],['together','Read together'],['reported-independent','Reported read independently']].map(([id,label])=>button(`data-window-reading="${id}" aria-pressed="${r.reading===id}"`,label,r.reading===id)).join('')}</div><p class="tiny">A separate report. It does not check decoding, fluency or understanding.</p></details>`;}
function readPage(r,v){const a=r.source.accounts.find(a=>a.id===v.account)||r.source.accounts[0];return `<h2 id="windows-prompt" tabindex="-1">What did each teller notice?</h2><p>Each teller knows part of this fictional event. The other account may add a different detail.</p><div class="windows-choices" role="group" aria-label="Choose an account">${r.source.accounts.map(x=>button(`data-window-account="${x.id}" aria-pressed="${a.id===x.id}"`,`Account ${x.id.toUpperCase()}: ${x.name}`,a.id===x.id)).join('')}</div>${windowReminder(r.source.id)}${account(r.source,a)}<details id="windows-other-account" data-visit="${r.id}"><summary>Read ${esc(r.source.accounts.find(x=>x.id!==a.id)?.name||'the other teller')}’s account too</summary>${r.source.accounts.filter(x=>x.id!==a.id).map(x=>account(r.source,x)).join('')}</details>${button('data-window-page="compare"','Compare the accounts',true)} ${button('data-window-page="message"','Make a reader’s message')}`;}
function claimResult(r,c,index){const current=index===r.claimChecks.length-1&&windowClaimMatches(r,c),claim=r.source.claims.find(x=>x.id===c.claim);return `<section class="windows-claim-result" tabindex="-1"><h3 data-window-claim-marker="${index}">${current?'Latest check of these choices':'Earlier recorded statement check'}</h3><p><strong>Recorded statement:</strong> ${esc(claim?.text||c.claim)}</p><p><strong>Chosen relationship:</strong> ${esc(relation(c.classification))}. <strong>Recorded expected relationship:</strong> ${esc(relation(c.expected))}.</p><p>Recorded relationship fits: ${c.classificationFits?'yes':'no'}. Recorded selected evidence: ${c.evidenceFits===null?'not automatically assessed':c.evidenceFits?'includes useful support':'supporting set not yet selected'}.</p><p class="windows-feedback">${esc(c.feedback)}</p><details><summary>Recorded selected lines (${c.lines.length})</summary>${sourceLines(r.source,c.lines)}</details>${c.evidenceFits===null?'<p>Selected lines are kept, not proof that a fact is missing. Reread both accounts for the missing detail.</p>':`<details><summary>Recorded useful lines (${c.used.length})</summary>${sourceLines(r.source,c.used,'No recorded useful lines.')}</details>`}${sourceDetails(r.source)}</section>`;}
function comparePage(r,v){const claim=r.source.claims.find(c=>c.id===r.currentClaim),draft=r.answers[r.currentClaim],latest=r.claimChecks.at(-1);return `<h2 id="windows-prompt" tabindex="-1">How does this statement fit?</h2><label for="windows-claim">Choose any statement</label><select id="windows-claim">${r.source.claims.map((c,n)=>`<option value="${c.id}"${c.id===r.currentClaim?' selected':''}>${n+1}. ${esc(c.text)}</option>`).join('')}</select><div class="windows-question"><p><strong>${esc(claim.text)}</strong></p><p>Use <strong>both accounts together</strong>, not just the last teller opened.</p></div><div class="windows-relationships" role="group" aria-label="How the statement fits both accounts">${windowRelations.map(x=>button(`data-window-relation="${x.id}" aria-pressed="${draft.classification===x.id}"`,`${x.label}${draft.classification===x.id?' · selected':''}`,draft.classification===x.id)).join('')}${button('data-window-relation="clear"','Leave relationship blank')}</div><p class="tiny">Choose lines below to support your reading. For “Not enough information,” you do not need to select lines to prove a missing fact. Your selections stay available.</p><h3>Tap any numbered lines; tap again to remove a selection</h3><div class="windows-choices windows-compare-account-switch" role="group" aria-label="Choose a displayed account">${r.source.accounts.map(a=>button(`data-window-account="${a.id}" aria-pressed="${v.account===a.id}"`,`Account ${a.id.toUpperCase()}: ${a.name}`,v.account===a.id)).join('')}</div><details id="windows-selected-clues" data-visit="${r.id}"><summary>Selected clues from both accounts (${draft.lines.length})</summary>${sourceLines(r.source,draft.lines)}</details><div class="windows-paired-accounts windows-live-compare">${r.source.accounts.map(a=>`<div class="windows-live-account" data-active="${v.account===a.id}">${account(r.source,a,{selectable:true,selected:draft.lines})}</div>`).join('')}</div><div class="windows-actions">${button('data-window-check-claim'+(draft.classification?'':' disabled'),'Check these choices',true)}${button('data-window-next','Another statement')}</div>${latest?claimResult(r,latest,r.claimChecks.length-1):''}<p class="tiny">The latest 8 statement checks stay here. A ninth removes the oldest statement check.</p>${r.claimChecks.length>1?`<details><summary>Earlier statement checks (${r.claimChecks.length-1})</summary>${r.claimChecks.slice(0,-1).map((c,i)=>claimResult(r,c,i)).join('')}</details>`:''}`;}
function messageResult(r,c,index){const own=c.card===null;return `<section class="windows-message-result" tabindex="-1"><h3 data-window-message-marker="${index}">${index===r.messageChecks.length-1&&windowMessageMatches(r,c)?own?'Kept words from this draft':'Latest ready-made note check':'Earlier recorded message work'}</h3><p><strong>Reader’s question:</strong> ${esc(r.source.reader.question)}</p>${own?`<p><strong>Own words, ungraded:</strong></p><div class="windows-exact">${c.words?esc(c.words):'<span class="tiny">No own words entered.</span>'}</div>${c.fits===null?'':`<p>Historical stored fit field: ${c.fits?'yes':'no'}. This is not an assessment of these words.</p>`}<p class="windows-feedback">${esc(c.feedback)}</p>`:`<p><strong>Ready-made note you checked:</strong></p><p class="windows-exact">${esc(c.text)}</p><p><strong>Ready-made note fit for the reader’s question, as recorded:</strong> ${c.fits===null?'ungraded':c.fits?'yes':'no'}.</p><p class="windows-feedback">${esc(c.feedback)}</p><p><strong>Own words at this moment (ungraded, not part of this card check):</strong></p><div class="windows-exact">${c.words?esc(c.words):'<span class="tiny">No own words entered.</span>'}</div>`}${sourceDetails(r.source)}</section>`;}
function messagePage(r){const reader=r.source.reader,latest=r.messageChecks.at(-1);return `<h2 id="windows-prompt" tabindex="-1">A note for ${esc(reader.name)}</h2><div class="windows-question"><p>${esc(reader.name)} knows only account ${esc(reader.knows.toUpperCase())}, ${esc(passageName(r.source,reader.knows))}’s account.</p><p><strong>${esc(reader.question)}</strong></p><p>Original incomplete note: “${esc(reader.original)}”</p></div><p>Choose a ready-made note that helps this reader. A true detail can still leave their question unanswered.</p><div class="windows-message-cards" role="group" aria-label="Ready-made notes for the reader">${reader.cards.map(c=>button(`data-window-card="${c.id}" aria-pressed="${r.selectedCard===c.id}"`,`${c.text}${r.selectedCard===c.id?' · selected':''}`,r.selectedCard===c.id)).join('')}${button('data-window-card="clear"','Leave card blank')}</div>${button('data-window-check-message'+(r.selectedCard?'':' disabled'),'Check the ready-made note',true)}<section class="windows-own-words"><label for="windows-words"><strong>Our words for a person to read</strong> (optional)</label><textarea id="windows-words" maxlength="1200" rows="4" aria-describedby="windows-words-help"></textarea><p class="tiny" id="windows-words-help">Up to 1200 characters in the browser’s text limit. Your spaces and line breaks stay exactly as entered. These words are ungraded and remain with this explorer’s browser work and notes download.</p>${button('data-window-keep-words','Keep our words')}<p class="tiny">You can also talk, read, sign, use AAC, or share away from the screen. That sharing is not observed here.</p></section>${latest?messageResult(r,latest,r.messageChecks.length-1):''}<details id="windows-message-passages" data-visit="${r.id}"><summary>Read both numbered accounts · original fiction</summary>${sources(r.source)}</details><p class="tiny">The latest 8 message records stay here. A ninth card check or kept-words record removes the oldest message record.</p>${r.messageChecks.length>1?`<details><summary>Earlier message work (${r.messageChecks.length-1})</summary>${r.messageChecks.slice(0,-1).map((c,i)=>messageResult(r,c,i)).join('')}</details>`:''}`;}
function capacity(v){const n=Math.max(0,v.rounds.length-11);return `<p class="tiny">Up to 12 readable visits stay here.${n?` Starting a story now removes the oldest ${n} readable ${n===1?'visit':'visits'}.`:' Starting a story keeps earlier visits within that limit.'} Changing passage length starts a separate visit to the same event.</p>`;}
function catalog(v){return `<section class="windows-catalog"><h2>Choose an original fictional story</h2><p>Three events, each told in two passage lengths. Choose either length freely.</p>${capacity(v)}<div class="windows-story-list">${windowStories.map(story=>`<form data-window-start="${story.id}"><h3>${esc(story.title)}</h3>${windowReminder(story.id)}<label for="windows-form-${story.id}">Passage length</label><select id="windows-form-${story.id}" name="form">${windowForms.map(f=>`<option value="${f.id}"${v.current?.source.id===story.id&&v.current.source.form===f.id?' selected':''}>${esc(f.label)}</option>`).join('')}</select><button class="secondary" type="submit">Read this story</button></form>`).join('')}</div></section>`;}
function histories(v){return `${v.rounds.length?`<details><summary>Our story visits (${v.rounds.length})</summary>${[...v.rounds].reverse().map(r=>`<p>${button(`data-window-resume="${r.id}"`,`Visit ${r.id}: ${r.source.title} · ${formName(r.source.form)}`)}</p>`).join('')}</details>`:''}${v.earlier.length?`<details><summary>Earlier unreadable work (${v.earlier.length})</summary><p>The original work stays unchanged.</p><pre>${esc(JSON.stringify(v.earlier,null,2))}</pre></details>`:''}`;}
export function twoWindowsPage(state){const v=windowsView(state),r=v.current,heading=`<header class="page-heading"><a class="back" href="#loft"><span aria-hidden="true">←</span> Back to the stage</a> <a class="back" href="#home">Take a break</a><h1>Two Windows</h1><p>Market stories need more than one view. Read two accounts and help a visitor find a useful detail.</p></header>`;if(v.status==='unavailable')return `<div class="windows-page">${heading}<section class="windows-sheet"><h2>Earlier work is safe</h2><p>This saved story desk uses a format we cannot continue here. It stays unchanged. The stage and garden remain open.</p><details><summary>See saved work</summary><pre>${esc(JSON.stringify(state.twoWindows,null,2))}</pre></details></section></div>`;
return `<div class="windows-page">${heading}<section class="windows-sheet"><nav class="windows-tabs" aria-label="Two Windows pages">${windowPages.map(p=>button(`data-window-page="${p}" aria-current="${v.page===p?'page':'false'}"`,p[0].toUpperCase()+p.slice(1),v.page===p)).join('')}</nav>${r?`<p class="windows-visit-label"><strong>${esc(r.source.title)}</strong> · ${esc(formName(r.source.form))}<br>Original fiction${r.familiar?' · A familiar event, perhaps in another passage length':''}</p>`:''}<p class="windows-status" id="windows-status" role="status" tabindex="-1"></p>${r?v.page==='compare'?comparePage(r,v):v.page==='message'?messagePage(r):readPage(r,v):`<h2 id="windows-prompt" tabindex="-1">Open a story at the quiet desk</h2><p>Each pair of tellers notices different details. Choose a story and passage length to begin.</p>${catalog(v)}`}<details id="windows-help"${r?.support.includes('help')?' open':''}><summary>Help us think about two accounts</summary><p>${help}</p>${hearButton(help,'Hear this help')}${r?button('data-window-support="together"',r.support.includes('together')?'Thinking together recorded':'We thought together'):''}<details id="windows-example" data-visit="${r?.id||''}"><summary>A small worked example</summary><p>One teller says, “The door was closed when I left.” Another says, “Later, I opened the door.” Together, the clues show the door changed. They do not tell us its color. A missing color is not a false color.</p></details></details>${r?readingReport(r):''}${r?`<details class="windows-more-stories"><summary>Start another story or passage length</summary>${catalog(v)}</details>`:''}</section>${histories(v)}</div>`;}
export function twoWindowsNotes(state){const v=windowsView(state);if(v.status==='missing')return '';if(v.status==='unavailable')return `<details class="panel"><summary>Two Windows · earlier format</summary><pre>${esc(JSON.stringify(state.twoWindows,null,2))}</pre></details>`;return `<details class="panel windows-page"><summary>Two Windows (${v.rounds.length} visits)</summary><p>Original fiction. Supplied statement/category/evidence and message-card practice, not independent writing, decoding, fluency or general source-reliability evidence. Reading reports, support and event familiarity are separate. Full exact words and frozen packs are in the notes download.</p>${v.rounds.map(r=>`<section><h3>Visit ${r.id}: ${esc(r.source.title)} · ${esc(formName(r.source.form))}</h3><p>Original fiction. Familiar event: ${r.familiar?'yes':'no'}. Reading report: ${esc(r.reading)}. Support: ${esc(r.support.join(', ')||'none recorded')}.</p>${sources(r.source)}<h4>Current statement drafts</h4>${r.source.claims.map(c=>`<p>${esc(c.text)} Relationship: ${esc(relation(r.answers[c.id].classification))}. Selected lines: ${esc(r.answers[c.id].lines.join(', ')||'none')}.</p>`).join('')}<p>Selected supplied card: ${esc(r.selectedCard||'none')}.</p><p>Own words draft, ungraded:</p><div class="windows-exact">${esc(r.words)}</div>${r.claimChecks.map((c,i)=>claimResult(r,c,i)).join('')}${r.messageChecks.map((c,i)=>messageResult(r,c,i)).join('')}</section>`).join('')}${v.earlier.length?`<pre>${esc(JSON.stringify(v.earlier,null,2))}</pre>`:''}</details>`;}
export function bindTwoWindows(state,{save,render,focus}){
 const show=(message='',target='#windows-prompt')=>{const id=windowsView(state).current?.id,open=[...document.querySelectorAll('.windows-page details[id][open]:not(#windows-help)')].filter(d=>Number(d.dataset.visit)===id).map(d=>d.id);save();render();if(windowsView(state).current?.id===id)for(const key of open){const d=document.getElementById(key);if(d)d.open=true;}const status=document.querySelector('#windows-status');if(status)status.textContent=message;focus(target);};
 const bind=(selector,fn)=>document.querySelectorAll(selector).forEach(b=>b.addEventListener('click',()=>fn(b)));
 const status=message=>{const s=document.querySelector('#windows-status');if(s)s.textContent=message;};
 bind('[data-window-page]',b=>{const ok=setWindowsPage(state,b.dataset.windowPage);show(ok?'':windowsView(state).current?'This page could not be opened.':'Choose a story to begin.');});
 document.querySelectorAll('[data-window-start]').forEach(form=>form.addEventListener('submit',e=>{e.preventDefault();const r=startWindows(state,form.dataset.windowStart,new FormData(form).get('form'));show(r?'A story visit is ready. Earlier work stays in its own visits.':'A new visit cannot be created because the saved visit numbers have reached the supported limit. Existing visits remain available.',r?'#windows-prompt':'#windows-status');}));
 bind('[data-window-account]',b=>{setWindowsAccount(state,b.dataset.windowAccount);show('',`[data-window-account="${b.dataset.windowAccount}"]`);});
 document.querySelector('#windows-claim')?.addEventListener('change',e=>{chooseWindowClaim(state,e.target.value);show('This statement’s own choices are waiting here.','#windows-claim');});
 bind('[data-window-next]',()=>{chooseWindowClaim(state,nextWindowClaim(state));show('Another statement is ready. Earlier choices are kept.','#windows-claim');});
 bind('[data-window-relation]',b=>{chooseWindowRelation(state,b.dataset.windowRelation==='clear'?null:b.dataset.windowRelation);show('Relationship choice updated. Earlier checks stay unchanged.',`[data-window-relation="${b.dataset.windowRelation}"]`);});
 bind('[data-window-line]',b=>{toggleWindowLine(state,b.dataset.windowLine);show('Selected lines updated. Earlier checks stay unchanged.',`[data-window-line="${b.dataset.windowLine}"]`);});
 bind('[data-window-check-claim]',()=>{const check=checkWindowClaim(state);show(check?'These statement choices have been checked.':'Choose a relationship before checking.',check?'.windows-claim-result':'#windows-status');});
 bind('[data-window-card]',b=>{chooseWindowCard(state,b.dataset.windowCard==='clear'?null:b.dataset.windowCard);show('Ready-made note choice updated. Earlier checks stay unchanged.',`[data-window-card="${b.dataset.windowCard}"]`);});
 bind('[data-window-check-message]',()=>{const check=checkWindowMessage(state);show(check?'This ready-made note has been checked for the reader’s question.':'Choose a ready-made note before checking.',check?'.windows-message-result':'#windows-status');});
 bind('[data-window-keep-words]',()=>{const record=keepWindowWords(state);show(record?'Your exact words are kept as ungraded work.':'The words could not be kept. The draft stays available.',record?'.windows-message-result':'#windows-status');});
 const words=document.querySelector('#windows-words');if(words){words.value=windowsView(state).current.words;words.addEventListener('input',()=>{const ok=setWindowWords(state,words.value);if(ok){save();const r=windowsView(state).current;document.querySelectorAll('[data-window-message-marker]').forEach(el=>{const c=r.messageChecks[Number(el.dataset.windowMessageMarker)];if(c)el.textContent=Number(el.dataset.windowMessageMarker)===r.messageChecks.length-1&&windowMessageMatches(r,c)?c.card===null?'Kept words from this draft':'Latest ready-made note check':'Earlier recorded message work';});status('Draft updated. Your words are ungraded.');}else status('The draft limit is 1200 characters in the browser’s text limit. No text was replaced.');});}
 bind('[data-window-reading]',b=>{setWindowReading(state,b.dataset.windowReading);show('Reading report recorded separately.',`[data-window-reading="${b.dataset.windowReading}"]`);});
 bind('[data-window-support]',b=>{addWindowSupport(state,b.dataset.windowSupport);show('Thinking together recorded.',`[data-window-support="${b.dataset.windowSupport}"]`);});
 bind('[data-window-resume]',b=>{const ok=resumeWindows(state,Number(b.dataset.windowResume));show(ok?'Earlier visit opened. Its own passages and recorded checks stay unchanged.':'That visit could not be opened.');});
 for(const [id,code]of [['windows-help','help'],['windows-example','example']])document.getElementById(id)?.addEventListener('toggle',e=>{if(e.currentTarget.open&&windowsView(state).current){addWindowSupport(state,code);save();}});
 document.querySelectorAll('.windows-sheet [data-speak]').forEach(b=>b.addEventListener('click',()=>{if(windowsView(state).current){addWindowSupport(state,'audio');save();}}));
}
